for i,d in enumerate(dyn):
    print(f"  dyn{i}: norm {np.linalg.norm(d):.4f}")

def full_resid_ratio(d, df, dp):
    aligned = d*np.exp(-2j*np.pi*(df*t+dp))
    return np.linalg.norm(aligned-ref)/norm_ref

print("\nBest full-spectrum residual ratio (coarse->fine grid) vs full-LSQ:")
for i in range(len(dyn)):
