    best=None
    for df in np.arange(-60,60,2.0):
        for dp in np.arange(-3.2,3.2,0.4):
            v=full_resid_ratio(dyn[i],df,dp)
            if best is None or v<best[0]: best=(v,df,dp)
    for step,fstep in [(0.5,0.1),(0.1,0.02)]:
